public struct LarkAuthConfig {
    public var appId: String
    public var appSecret: String

    /// Default memberwise initializers are never public by default, so we
    /// declare one manually.
    public init(appId: String, appSecret: String) {
        self.appId = appId
        self.appSecret = appSecret
    }
}

extension LarkAuthConfig: Equatable, Hashable {
    public static func == (lhs: LarkAuthConfig, rhs: LarkAuthConfig) -> Bool {
        if lhs.appId != rhs.appId {
            return false
        }
        if lhs.appSecret != rhs.appSecret {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(appId)
        hasher.combine(appSecret)
    }
}

