    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LarkFfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        case 1: return try .ApiError(
                msg: FfiConverterString.read(from: &buf)
            )
        case 2: return try .AuthError(
                msg: FfiConverterString.read(from: &buf)
            )
        case 3: return try .IoError(
                msg: FfiConverterString.read(from: &buf)
            )
        default: throw UniffiInternalError.unexpectedEnumCase
        }
