public protocol SyncProgressCallback: AnyObject {
    func onProgress(progress: SyncProgressEventDto)

    func onLog(level: String, message: String)
}

/// Magic number for the Rust proxy to call using the same mechanism as every other method,
/// to free the callback once it's dropped by Rust.
private let IDX_CALLBACK_FREE: Int32 = 0
// Callback return codes
private let UNIFFI_CALLBACK_SUCCESS: Int32 = 0
private let UNIFFI_CALLBACK_ERROR: Int32 = 1
private let UNIFFI_CALLBACK_UNEXPECTED_ERROR: Int32 = 2

/// Put the implementation in a struct so we don't pollute the top-level namespace
private enum UniffiCallbackInterfaceSyncProgressCallback {
    /// Create the VTable using a series of closures.
    /// Swift automatically converts these into C callback functions.
    nonisolated(unsafe) static var vtable: UniffiVTableCallbackInterfaceSyncProgressCallback = .init(
        onProgress: { (
            uniffiHandle: UInt64,
            progress: RustBuffer,
            _: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceSyncProgressCallback.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.onProgress(
                    progress: FfiConverterTypeSyncProgressEventDto.lift(progress)
                )
            }

            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        onLog: { (
            uniffiHandle: UInt64,
            level: RustBuffer,
            message: RustBuffer,
            _: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceSyncProgressCallback.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.onLog(
                    level: FfiConverterString.lift(level),
                    message: FfiConverterString.lift(message)
                )
            }

            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) in
            let result = try? FfiConverterCallbackInterfaceSyncProgressCallback.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface SyncProgressCallback: handle missing in uniffiFree")
            }
        }
    )
}

private func uniffiCallbackInitSyncProgressCallback() {
    uniffi_larksync_ffi_fn_init_callback_vtable_syncprogresscallback(&UniffiCallbackInterfaceSyncProgressCallback.vtable)
}

